"""Parser for Python uv.lock files."""

from __future__ import annotations

import tomllib
from pathlib import Path
from typing import Any

from lh_sbom_auditor.models import Checksum, DependencyGraph, Ecosystem, Package
from lh_sbom_auditor.parsers.base import AbstractLockfileParser


class UvLockParser(AbstractLockfileParser):
    """Parses uv.lock files generated by uv package manager."""

    @property
    def name(self) -> str:
        """Name of parser."""
        return "uv.lock"

    @property
    def ecosystem(self) -> Ecosystem:
        """Target ecosystem."""
        return Ecosystem.PYPI

    def can_parse(self, file_path: Path) -> bool:
        """Check if file is a uv.lock file."""
        if file_path.name == "uv.lock":
            return True
        if file_path.suffix == ".lock":
            try:
                content = file_path.read_text(encoding="utf-8")
                return "[[package]]" in content and "version = 1" in content
            except OSError:
                return False
        return False

    def parse(self, file_path: Path) -> DependencyGraph:
        """Parse uv.lock into a normalized DependencyGraph."""
        content = file_path.read_text(encoding="utf-8")
        data = tomllib.loads(content)

        raw_packages: list[dict[str, Any]] = data.get("package", [])

        # Identify potential root package (e.g. virtual or editable root)
        root_name = file_path.parent.name or "root-project"
        root_version = "0.1.0"
        root_direct_dep_names: set[str] = set()
        virtual_root_found = False

        for raw_pkg in raw_packages:
            source = raw_pkg.get("source", {})
            if isinstance(source, dict) and ("virtual" in source or "editable" in source):
                root_name = raw_pkg.get("name", root_name)
                root_version = raw_pkg.get("version", root_version)
                virtual_root_found = True
                for dep in raw_pkg.get("dependencies", []):
                    if isinstance(dep, dict) and "name" in dep:
                        root_direct_dep_names.add(dep["name"].lower())
                    elif isinstance(dep, str):
                        root_direct_dep_names.add(dep.split(";")[0].split("=")[0].strip().lower())
                break

        graph = DependencyGraph(
            root_name=root_name,
            root_version=root_version,
            ecosystem=Ecosystem.PYPI,
            manifest_path=str(file_path),
        )

        for raw_pkg in raw_packages:
            pkg_name = raw_pkg.get("name", "")
            if not pkg_name:
                continue

            source = raw_pkg.get("source", {})
            # If this is the virtual root itself, skip adding it as a library component
            if (
                virtual_root_found
                and isinstance(source, dict)
                and ("virtual" in source or "editable" in source)
            ):
                continue

            version = str(raw_pkg.get("version", "0.0.0"))
            is_direct = pkg_name.lower() in root_direct_dep_names

            # Extract dependencies
            dep_names: list[str] = []
            for dep in raw_pkg.get("dependencies", []):
                if isinstance(dep, dict) and "name" in dep:
                    dep_name = dep["name"]
                    dep_names.append(dep_name)
                    graph.add_dependency(pkg_name, dep_name)
                elif isinstance(dep, str):
                    clean_dep = dep.split(";")[0].split("=")[0].strip()
                    dep_names.append(clean_dep)
                    graph.add_dependency(pkg_name, clean_dep)

            # Checksums and resolved url
            checksums: list[Checksum] = []
            resolved_url: str | None = None

            sdist = raw_pkg.get("sdist")
            if isinstance(sdist, dict):
                resolved_url = sdist.get("url")
                h = sdist.get("hash")
                if isinstance(h, str) and ":" in h:
                    alg, val = h.split(":", 1)
                    checksums.append(Checksum(algorithm=alg.upper(), value=val))

            for wheel in raw_pkg.get("wheels", []):
                if isinstance(wheel, dict):
                    if not resolved_url:
                        resolved_url = wheel.get("url")
                    h = wheel.get("hash")
                    if isinstance(h, str) and ":" in h:
                        alg, val = h.split(":", 1)
                        cs = Checksum(algorithm=alg.upper(), value=val)
                        if cs not in checksums:
                            checksums.append(cs)

            package = Package(
                name=pkg_name,
                version=version,
                ecosystem=Ecosystem.PYPI,
                direct=is_direct,
                is_dev=False,
                license=None,
                checksums=checksums,
                resolved_url=resolved_url,
                dependencies=dep_names,
                is_pinned=True,
            )
            graph.add_package(package)

        # If no virtual root was found, determine direct dependencies
        # (packages not required by any other package)
        if not virtual_root_found:
            all_dependent_names = {dep.lower() for deps in graph.edges.values() for dep in deps}
            for pkg in graph.all_packages:
                if pkg.name.lower() not in all_dependent_names:
                    pkg.direct = True

        return graph
